//! Value object representing an immutable embedding vector.

use crate::domain::errors::DomainError;

/// An immutable vector generated by an embedding model.
///
/// Embedding values use `f32`, matching the representation commonly used
/// by machine-learning inference engines and vector databases.
#[derive(Debug, Clone, PartialEq)]
pub struct Embedding {
    vector: Vec<f32>,
}

impl Embedding {
    /// Creates an embedding after validating its values.
    pub fn new(vector: Vec<f32>) -> Result<Self, DomainError> {
        if vector.is_empty() {
            return Err(DomainError::EmptyEmbedding);
        }

        if vector.iter().any(|value| !value.is_finite()) {
            return Err(DomainError::NonFiniteEmbeddingValue);
        }

        Ok(Self { vector })
    }

    /// Returns the embedding vector as a slice.
    pub fn vector(&self) -> &[f32] {
        &self.vector
    }

    /// Returns the number of dimensions in the embedding.
    pub fn dimension(&self) -> usize {
        self.vector.len()
    }
}
